async function GBe(e) {
  let t = e.panel,
    n = e.pick(WBe);
  t.say(null, r7.come(n.who), !1);
  let r = n.adults * n7.adult + n.kids * n7.child + n.small * n7.infant,
    i = [
      r,
      r + 100,
      r - 100 > 0 ? r - 100 : r + 200,
      n.adults * n7.adult + (n.kids + n.small) * n7.adult,
    ]
      .filter((e, t, n) => n.indexOf(e) === t)
      .slice(0, 4);
  for (; i.length < 3;) i.push(i[i.length - 1] + 50);
  let a = i.sort(() => e.rng.next() - 0.5);
  if (
    (e.score(
      await t.pick({
        prompt: r7.feeQ(n.who),
        options: a.map((e) => ({ label: N(Z5(e), Z5(e), Z5(e)), icon: `♨️` })),
        correct: a.indexOf(r),
        secs: 9 / e.pace + 2,
      }),
    ),
    e.over)
  )
    return;
  let o = r;
  if (e.rng.next() < 0.45) {
    let r = e.rng.next() < 0.75,
      i = !r || e.rng.next() < 0.4;
    (r && t.say(null, r7.towel),
      i && t.say(null, r7.soap),
      (o += (r ? HBe * n.adults : 0) + (i ? UBe : 0)));
    let a = e.rng.next() < 0.6 ? o : o + (e.rng.next() < 0.5 ? 50 : -50);
    if (
      (e.score(
        await t.pick({
          prompt: r7.extraQ(a),
          options: [
            { label: r7.yes, icon: `⭕` },
            { label: r7.no, icon: `❌` },
          ],
          correct: a === o ? 0 : 1,
          secs: 7,
        }),
      ),
      e.over)
    )
      return;
  }
  let s = o <= 1e3 ? 1e3 : o <= 2e3 ? 2e3 : 5e3;
  t.say(null, r7.pay(s, o));
  let c = X5(e, s - o);
  if (
    (e.score(
      await t.pick({
        prompt: r7.changeQ(s, o),
        options: c.map((e) => ({ label: N(Z5(e), Z5(e), Z5(e)), icon: `💴` })),
        correct: c.indexOf(s - o),
        secs: 9 / e.pace + 2,
      }),
    ),
    !e.over)
  ) {
    if (n.adults === 1 && n.kids === 0 && e.rng.next() < 0.4) {
      let n = e.rng.next() < 0.5;
      if (
        (t.say(
          null,
          n
            ? N(`（是位男客人）`, `(A man)`, `（男性のお客さん）`)
            : N(`（是位女客人）`, `(A woman)`, `（女性のお客さん）`),
          !1,
        ),
        e.score(
          await t.pick({
            prompt: r7.noren,
            options: [
              { label: r7.men, icon: `🟦` },
              { label: r7.women, icon: `🟥` },
            ],
            correct: +!n,
            secs: 5,
          }),
        ),
        e.over)
      )
        return;
    }
    (n.who.en === `A tourist` &&
      e.rng.next() < 0.7 &&
      (t.say(null, r7.manners, !1),
      e.score(
        await t.pick({
          prompt: r7.mannersQ,
          options: [{ label: r7.mOk }, { label: r7.mNo1 }, { label: r7.mNo2 }],
          correct: 0,
          secs: 9,
        }),
      ),
      e.over)) ||
      (t.say(null, r7.thanks),
      e.served(),
      e.rng.next() < 0.3 &&
        (await t.beat(0.6),
        t.say(null, r7.milk),
        e.score(
          await t.timing({
            prompt: r7.milkQ,
            zone: [0.4, 0.62],
            perfect: [0.47, 0.55],
            speed: 0.8 * e.pace,
            secs: 6,
          }),
        )),
      await t.beat(0.5));
  }
}
