async function JBe(e) {
  let t = e.panel;
  if (
    (e.score(
      await t.rhythm({
        prompt: a7.patterQ,
        words: [`さあ`, `さあ`, `寄って`, `らっしゃい`],
        bpm: 96 + e.progress * 24,
      }),
    ),
    e.over)
  )
    return;
  let n = 0.62 + e.rng.next() * 0.16,
    r = Math.max(0.1, 0.18 - e.progress * 0.06);
  if (
    (e.score(
      await t.timing({
        prompt: a7.heatQ,
        zone: [n, n + r],
        perfect: [n + r * 0.3, n + r * 0.7],
        speed: 0.3 * e.pace,
        fill: !0,
      }),
    ),
    e.over)
  )
    return;
  t.say(Q.shimizu.name, a7.sold);
  let i = Math.floor(e.rng.next() * 3);
  (t.say(null, a7.hand(i), !1),
    e.score(
      await t.pick({
        prompt: a7.handQ,
        options: [
          { label: a7.left, icon: `👈` },
          { label: a7.front, icon: `👆` },
          { label: a7.right, icon: `👉` },
        ],
        correct: i,
        secs: 3.5 / e.pace + 1.5,
      }),
    ),
    !e.over &&
      (e.score(await t.mash({ prompt: a7.stuff, target: 9, secs: 3.5 })),
      !e.over && (t.say(null, a7.thanks), e.served())));
}
